	@Test
	void nestedBlankNodesWithCollidingHashesRemainDistinct() throws Exception {
		var factory = SimpleValueFactory.getInstance();
		IRI subject = factory.createIRI("urn:subject");
		IRI predicate = factory.createIRI("urn:predicate");
		TripleTerm first = factory.createTripleTerm(subject, predicate, factory.createBNode("Aa\n"));
		TripleTerm second = factory.createTripleTerm(subject, predicate, factory.createBNode("BB\n"));
		List<String> names = List.of("first", "second");
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		QueryResultIO.writeTuple(new IteratingTupleQueryResult(names,
				List.of(new ListBindingSet(names, first, second), new ListBindingSet(names, first, second))),
				TupleQueryResultFormat.CSV, output);

		QueryResultCollector parsed = new QueryResultCollector();
		QueryResultIO.parseTuple(new ByteArrayInputStream(output.toByteArray()), TupleQueryResultFormat.CSV,
				parsed, factory);
		assertEquals(2, parsed.getBindingSets().size());
		Value firstParsed = ((TripleTerm) parsed.getBindingSets().get(0).getValue("first")).getObject();
		Value secondParsed = ((TripleTerm) parsed.getBindingSets().get(0).getValue("second")).getObject();
		assertNotEquals(firstParsed, secondParsed);
		assertEquals(firstParsed, ((TripleTerm) parsed.getBindingSets().get(1).getValue("first")).getObject());
		assertEquals(secondParsed, ((TripleTerm) parsed.getBindingSets().get(1).getValue("second")).getObject());
	}

