	@Test
	void recordSeparatorReaderReturnsBeforeNextChunkArrives() throws Exception {
		boolean[] releaseNextChunk = { false };
		Reader chunks = new Reader() {
			private int step;

			@Override
			public int read(char[] buffer, int offset, int length) {
				if (step == 0) {
					buffer[offset] = '\r';
					step++;
					return 1;
				}
				if (!releaseNextChunk[0]) {
					throw new AssertionError("Reader requested the next chunk before returning the current one");
				}
				if (step == 1) {
					"\nnext".getChars(0, 5, buffer, offset);
					step++;
					return 5;
				}
				return -1;
			}

			@Override
			public void close() {
			}
		};

		try (Reader normalized = new SPARQLResultsCSVParser.CSVRecordSeparatorReader(chunks)) {
			char[] buffer = new char[16];
			assertEquals(1, normalized.read(buffer, 0, buffer.length));
			assertEquals('\n', buffer[0]);
			releaseNextChunk[0] = true;
			assertEquals(4, normalized.read(buffer, 0, buffer.length));
			assertEquals("next", new String(buffer, 0, 4));
		}
	}
